class Complex {
  final int real;
  final int imag;

  Complex(this.real, this.imag);

  // Conjugate inverse (e.g., 2+4i -> 2-4i)
  Complex inv() => Complex(real, -imag);

  // Complex multiplication: (a+bi)*(c+di) = (ac−bd) + (ad+bc)i
  static Complex mult(Complex a, Complex b) {
    return Complex(
      a.real * b.real - a.imag * b.imag,
      a.real * b.imag + a.imag * b.real,
    );
  }

  @override
  String toString() => imag >= 0 
      ? '($real + ${imag}i)' 
      : '($real - ${-imag}i)';
}

void main() {
  final c1 = Complex(2, 4);   // First complex number
  final c2 = Complex(6, -2);  // Second complex number

  print(c1);         // Prints: (2 + 4i)
  print(c2);         // Prints: (6 - 2i)

  final invC1 = c1.inv();
  print(invC1);      // Prints: (2 - 4i)

  final product = Complex.mult(c2, c1);
  print(product);    // Prints: (20 + 20i)
}
```

