String lcsDynamic(String s1, String s2) {
  if (s1.isEmpty || s2.isEmpty) return "";

  final m = s1.length;
  final n = s2.length;

  // Initialize DP table with dimensions (m+1) x (n+1)
  final dp = List.generate(m + 1, (_) => List.filled(n + 1, 0));

  // Populate DP table
  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (s1[i - 1] == s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = (dp[i - 1][j] > dp[i][j - 1]) ? dp[i - 1][j] : dp[i][j - 1];
      }
    }
  }

  // Backtrack to build LCS in reverse
  final reversedLcs = StringBuffer();
  int i = m, j = n;
  while (i > 0 && j > 0) {
    if (s1[i - 1] == s2[j - 1]) {
      reversedLcs.write(s1[i - 1]);
      i--;
      j--;
    } else if (dp[i - 1][j] > dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }

  // Reverse the result to correct order
  final reversedString = reversedLcs.toString();
  final result = StringBuffer();
  for (int idx = reversedString.length - 1; idx >= 0; idx--) {
    result.write(reversedString[idx]);
  }

  return result.toString();
}
```

