void heapSort(List<num> arr) {
  final n = arr.length;

  // Build max-heap from the array
  for (int i = (n >> 1) - 1; i >= 0; i--) {
    _siftDown(arr, n, i);
  }

  // Extract elements from heap
  for (int i = n - 1; i > 0; i--) {
    // Move root (max) to end
    final swap = arr[0];
    arr[0] = arr[i];
    arr[i] = swap;

    // Maintain heap property
    _siftDown(arr, i, 0);
  }
}

void _siftDown(List<num> arr, int heapSize, int root) {
  int current = root;

  while (true) {
    final leftChild = (current << 1) + 1;
    final rightChild = leftChild + 1;
    int maxIndex = current;

    // Find largest among current, left, and right
    if (leftChild < heapSize && arr[leftChild] > arr[maxIndex]) {
      maxIndex = leftChild;
    }
    if (rightChild < heapSize && arr[rightChild] > arr[maxIndex]) {
      maxIndex = rightChild;
    }

    // Heap property satisfied
    if (maxIndex == current) break;

    // Swap and continue sifting
    final temp = arr[current];
    arr[current] = arr[maxIndex];
    arr[maxIndex] = temp;

    current = maxIndex;
  }
}
```

