func fullAdder(_ a: Int, _ b: Int, carry carryIn: Int) -> (sum: Int, carry: Int) {
    // First half-adder: a + b
    let (sum1, carry1) = halfAdder(a, b)

    // Second half-adder: intermediate sum + carryIn
