    private(set) var head: Node?
    private(set) var tail: Node?

    class Node {
        weak var prev: Node?  // Weak reference to prevent retain cycles
        var next: Node?
        let value: T

        init(prev: Node?, next: Node?, value: T) {
            self.prev = prev
            self.next = next
            self.value = value
        }
    }

    func prepend(item: T) {
