func calculate(epsilon: Double) -> Double {
    // Initialize sum with first two terms: 1/0! + 1/1! = 1 + 1
    var sum = 2.0
    // factorial tracks n! for current iteration (starts at 1! = 1)
    var factorial: UInt64 = 1
    // n starts at 2 (next term to compute)
    var n: UInt64 = 2

    while true {
        // Compute next factorial = n! = (n-1)! * n
        let (newFactorial, factorialOverflow) = factorial.multipliedReportingOverflow(by: n)
        guard !factorialOverflow else {
            fatalError("Factorial computation overflow")
        }
        factorial = newFactorial

        // Calculate current term: 1/n!
        let term = 1.0 / Double(factorial)
        // Add term to cumulative sum
        sum += term

        // Terminating condition: stop when added term < epsilon
        if term < epsilon {
            break
        }

        // Prepare next n value (n += 1)
        let (nextN, nOverflow) = n.addingReportingOverflow(1)
        guard !nOverflow else {
            fatalError("Iteration counter overflow")
        }
        n = nextN
    }

    return sum
}
```

### Key Implementation Notes:
1. **Initial State**: 
   - `sum = 2.0` accounts for terms at n=0 (1/0! = 1) and n=1 (1/1! = 1)
   - `factorial = 1` (1! value for n=1)
   - `n = 2` (first term to compute in loop)

2. **Loop Execution**:
   - Computes factorial iteratively using overflow-checked multiplication
   - Calculates term as `1 / factorial`
   - Adds term to sum before checking epsilon condition
   - Breaks loop when term < epsilon (last added term is insignificant)

3. **Overflow Handling**:
   - Uses `multipliedReportingOverflow` and `addingReportingOverflow` to detect integer overflows
   - Triggers fatal errors on overflow (matches assembly's UD2 trap behavior)

