    // Step 1: Clamp input to [-64, 64] range
    let clampedBits: Int
    if bits < -64 {
        clampedBits = -64
    } else if bits > 64 {
        clampedBits = 64
    } else {
        clampedBits = bits
    }

    // Step 2: Compute base mask
    let mask64: UInt64
    if clampedBits < 0 {
        mask64 = 0xFFFF_FFFF_FFFF_FFFF
    } else if clampedBits < 64 {
        mask64 = 1 << clampedBits
    } else {
        mask64 = 0
    }

