    // Handle edge cases
    if n < 2 { return false }
    if n == 2 { return true }
    if n % 2 == 0 { return false }
    if n == 3 { return true }
    if n % 3 == 0 { return false }

    var divisor: Int = 5

    while true {
        // Check if divisor squared would cause overflow
        let (square, overflowSquare) = divisor.multipliedReportingOverflow(by: divisor)
        guard !overflowSquare else { 
            fatalError("Multiplication overflow") 
        }

        // Terminate loop when divisor^2 exceeds n
        if n < square { 
            break
        }

        // Check divisor != 0 and prevent division overflow edge case
        guard divisor != 0, !(n == Int.min && divisor == -1) else {
            fatalError("Division error")
        }

        // Test divisibility
        if n % divisor == 0 {
            return false
        }

        // Calculate next divisor (divisor + 2)
        let (next, overflowAdd) = divisor.addingReportingOverflow(2)
        guard !overflowAdd else { 
            fatalError("Addition overflow") 
        }

        // Check secondary divisor
        guard next != 0, !(n == Int.min && next == -1) else {
            fatalError("Division error")
        }

        if n % next == 0 {
            return false
        }

        // Advance to next pair (divisor + 6)
        let (nextDivisor, overflowStep) = next.addingReportingOverflow(4)
        guard !overflowStep else { 
            fatalError("Addition overflow") 
        }
        divisor = nextDivisor
    }

    return true
}
```

