func deconv(g: [Double], f: [Double]) -> [Double] {
  let fs = f.count
  var ret = [Double](repeating: 0, count: g.count - fs + 1)

  for n in 0..<ret.count {
    ret[n] = g[n]
    let lower = n >= fs ? n - fs + 1 : 0

    for i in lower..<n {
      ret[n] -= ret[i] * f[n - i]
    }

    ret[n] /= f[0]
  }

  return ret
}

