func mu(number: Int) -> Int {
    var n = number
    if n % 4 == 0 {
        return 0
    }
    var primeFactors = 0
    if n % 2 == 0 {
        primeFactors += 1
        n /= 2
    }
    var p = 3
    while p * p <= n {
        if n % p == 0 {
            n /= p
            if n % p == 0 {
                return 0
            }
            primeFactors += 1
        }
        p += 2
    }
    if (n > 1) {
        primeFactors += 1
    }
    return primeFactors % 2 == 0 ? 1 : -1
}

class PrimeSieve {
    var composite: [Bool]
    init(size: Int) {
        composite = Array(repeating: false, count: size/2)
        var p = 3
        while p * p <= size {
            if !composite[p/2 - 1] {
                let inc = p * 2
                var q = p * p
                while q <= size {
                    composite[q/2 - 1] = true
                    q += inc
                }
            }
            p += 2
        }
    }
}
