extension String {
    func splitOnChanges() -> [String] {
        // Handle empty string case
        guard !isEmpty else { return [] }

        var result = [String]()
        var currentChar = self.first!
        var currentSegment = String(currentChar)

        // Iterate through remaining characters
        for char in dropFirst() {
            if char == currentChar {
                // Append to current segment if same character
                currentSegment.append(char)
            } else {
                // Finalize current segment and start new one
                result.append(currentSegment)
                currentSegment = String(char)
                currentChar = char
            }
        }

        // Add the last segment
        result.append(currentSegment)
        return result
    }
}
```

