class Percolate {
    // Grid properties (offsets from assembly)
    let gridSize: Int        // Stored at offset 0x18
    let bottomRowStart: Int  // Stored at offset 0x28 (gridSize*(gridSize-1))
    var grid: [Int]          // Stored at offset 0x20

    // Global flags (bit masks)
    static let filledFlag: Int = 1 << 0
    static let bottomWallFlag: Int = 1 << 1
    static let rightWallFlag: Int = 1 << 2

    init(gridSize: Int) {
        self.gridSize = gridSize
        self.bottomRowStart = gridSize * (gridSize - 1)
        self.grid = Array(repeating: 0, count: gridSize * gridSize)
    }

    func fill(at index: Int) -> Bool {
        // Check if already filled
        if grid[index] & Percolate.filledFlag != 0 {
            return false
        }

        // Mark current cell as filled
        grid[index] |= Percolate.filledFlag

        // Check if reached bottom row
        if index >= bottomRowStart {
            return true
        }

        // Define neighbor checks: (offset, wallFlag)
        let directions = [
            (gridSize, Percolate.bottomWallFlag),  // Down
            (1, Percolate.rightWallFlag),          // Right
            (-1, Percolate.rightWallFlag),         // Left
            (-gridSize, Percolate.bottomWallFlag)  // Up
        ]

        for (offset, wallFlag) in directions {
            let newIndex = index + offset

            // Skip invalid indices
            guard newIndex >= 0, newIndex < grid.count else {
                continue
            }

            // Skip if blocked by wall
            guard grid[newIndex] & wallFlag == 0 else {
                continue
            }

            // Recursive check
            if fill(at: newIndex) {
                return true
            }
        }

        return false
    }
}
```

