  var count = 0, i = 0, probe = 1

  while true {
    probe += probe
    i += 1

    if probe >= ten18 {
      while true {
        if probe >= ten18 {
          probe /= 10
        }

        if probe / digits == L {
          count += 1

          if count >= n {
            count -= 1
            break
          }
