        probe += probe
        i += 1
      }
    }

    let probeString = String(probe)
    var len = asString.count

    if asString.count > probeString.count {
      len = probeString.count
    }

    if probeString.prefix(len) == asString {
      count += 1

      if count >= n {
        break
      }
    }
  }

  return i
}

